class Server:

    VALID_SEND_TYPE = "send"
    VALID_RECEIVE_TYPE = "receive"

    def __init__(self):
        self._white_list = []
        self._send_struct = {}
        self._receive_struct = {}

    @property
    def white_list(self):
        return self._white_list

    @white_list.setter
    def white_list(self, value):
        self._white_list = value

    @property
    def send_struct(self):
        return self._send_struct

    @send_struct.setter
    def send_struct(self, value):
        self._send_struct = value

    @property
    def receive_struct(self):
        return self._receive_struct

    @receive_struct.setter
    def receive_struct(self, value):
        self._receive_struct = value

    def _is_valid_info(self, info):
        return isinstance(info, dict) and "addr" in info and "content" in info

    def _safe_return_content(self, content):
        return content

    def add_white_list(self, addr):
        if addr in self.white_list:
            return False
        self.white_list.append(addr)
        return self.white_list

    def del_white_list(self, addr):
        if addr not in self.white_list:
            return False
        self.white_list.remove(addr)
        return self.white_list

    def recv(self, info):
        if not self._is_valid_info(info):
            return -1
        addr = info["addr"]
        if addr not in self.white_list:
            return False
        self.receive_struct = {"addr": addr, "content": info["content"]}
        return self._safe_return_content(self.receive_struct["content"])

    def send(self, info):
        if not self._is_valid_info(info):
            return "info structure is not correct"
        self.send_struct = {"addr": info["addr"], "content": info["content"]}

    def show(self, type):
        if type == self.VALID_SEND_TYPE:
            return self.send_struct
        elif type == self.VALID_RECEIVE_TYPE:
            return self.receive_struct
        else:
            return False
